public uint ReverseBits(uint n) {
    uint r = 0;
    for (int i = 0; i < 32; i++) {
        r = (r << 1) | (n & 1);   // the lowest bit of n goes into the lowest bit of r
        n >>= 1;                  // uint: zeros come in from the left
    }
    return r;
}

