public uint ReverseBits(uint n) {
    n = (n >> 16) | (n << 16);                                // halves
    n = ((n & 0xFF00FF00) >> 8) | ((n & 0x00FF00FF) << 8);    // bytes
    n = ((n & 0xF0F0F0F0) >> 4) | ((n & 0x0F0F0F0F) << 4);    // nibbles
    n = ((n & 0xCCCCCCCC) >> 2) | ((n & 0x33333333) << 2);    // pairs
    n = ((n & 0xAAAAAAAA) >> 1) | ((n & 0x55555555) << 1);    // neighbouring bits
    return n;
}
